import assert from 'node:assert/strict';
import vm from 'node:vm';
import worker from '../src/index.js';

// Inspect the HTML actually generated by the Worker, not a hand-written copy.
const html = await (await worker.fetch(new Request('https://credizas.test/'), {})).text();
assert.match(html, /id="productSearch"/);
assert.match(html, /id="productSearchBtn"/);
assert.match(html, /id="productResults" class="product-results hidden"/);
assert.match(html, /id="selectedProduct" class="selected-product hidden"/);
const productRegion = html.slice(html.indexOf('class="field product-search-wrap"'), html.indexOf('name="solicitud.monto_total_solicitado"'));
const idx = id => productRegion.indexOf(`id="${id}"`);
assert(idx('productSearch') >= 0 && idx('productResults') > idx('productSearchBtn'));
assert(idx('selectedProduct') > idx('productResults'), 'La lista de resultados debe estar ANTES de los productos ya agregados');
const resultsCSS = html.match(/\.product-results\{([^}]+)\}/)?.[1];
assert(resultsCSS, 'Falta CSS de la lista de resultados');
assert.match(resultsCSS, /(?:^|;)position:static(?:;|$)/, 'Los resultados deben permanecer en el flujo inmediatamente después del buscador');
assert.doesNotMatch(resultsCSS, /position:absolute|top:100%|bottom:|left:0;right:0/, 'Los resultados no deben anclarse al final del contenedor de productos');
assert.match(resultsCSS, /max-height:340px/);
assert.match(resultsCSS, /overflow-y:auto/);
assert.match(html, /function selectCatalogProduct\(p\)/);
assert.match(html, /renderSelectedProducts\(\);updateProductTotal\(\)/);
for (const mode of ['combo','individual','fcb']) assert(html.includes(`data-catalog-mode="${mode}"`));
for (const script of [...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/gi)].map(m=>m[1]).filter(Boolean)) new vm.Script(script);
console.log('OK V23.5: buscador y resultados en orden visible, sin posicionamiento absoluto debajo de tarjetas; scroll de resultados, modos Combo/Individual/FCB y JS válido.');
